insert into catatan_surveyor (kos_id, hal_baik, perlu_diketahui, kesan_pemilik, red_flags) values
  ('314d7462-fc01-465d-af1b-7c1f9617be10', array['Mesin cuci 2 unit gratis, jarang antre.', 'Halaman depan ada pohon mangga rindang, sore hari adem.', 'Penjaga 24 jam, gerbang digembok jam 23.00 tapi penghuni pegang kunci.']::text[], array['Kamar lantai 1 dekat dapur, agak berisik saat jam masak malam.', 'Kontrak minimal 3 bulan, bayar di muka bulan pertama.', 'Jalan depan macet jam pulang kerja, motor tetap bisa lewat.']::text[], 'Sangat rapi, punya buku catatan kerusakan tiap kamar.', '{}'::text[]),
  ('5b405e8f-c1ef-4199-adf5-15e266976231', array['Dapur bersama luas, kompor 2 tungku, kulkas 2 pintu.', 'Kunci kamar ganda, pemilik tidak pegang duplikat tanpa izin.', 'Ada CCTV di gerbang dan koridor tiap lantai.']::text[], array['Motor parkir di gang depan, tidak beratap.', 'Sumur bor, rasa air sedikit payau; untuk minum beli galon.', 'Air kadang keruh setelah hujan deras, pemilik bilang sedang pasang filter.']::text[], 'Ibu kos zaman dulu: perhatian, sesekali bawakan makanan.', array['Instalasi listrik terbuka di koridor lantai 2, kabel menjuntai dekat pipa air.']::text[]),
  ('1552b409-7ddb-40ce-af27-1f8d7789bf29', array['Dinding bata plester, suara TV kamar sebelah nyaris tidak terdengar.', 'Gang cukup lebar, mobil bisa masuk sampai depan kos.', 'Lantai koridor keramik, tidak ada bau lembap.']::text[], array['Sebelah kos ada bengkel motor, ramai jam 09.00–17.00.', 'Mayoritas penghuni karyawan shift, koridor sepi siang hari.', 'WiFi bayar sendiri Rp75.000 per bulan ke pemilik.']::text[], 'Dikelola anak pemilik, cepat tanggap soal kerusakan.', '{}'::text[]),
  ('54f13162-9ae4-4f57-a941-1ff11a24d51b', array['Sampah diangkut tiap pagi, tidak ada tumpukan di depan.', 'Kamar mandi dalam berkeramik penuh, tidak ada nat menghitam.', 'Ventilasi silang di semua kamar, tidak pengap siang hari.']::text[], array['Mayoritas penghuni karyawan shift, koridor sepi siang hari.', 'Kamar mandi dalam hanya untuk tipe AC.', 'Pembayaran hanya transfer, tidak terima tunai.']::text[], 'Pensiunan yang senang mengobrol, hafal nama semua penghuni.', '{}'::text[]),
  ('38ac44a2-3385-43d9-ab06-c953f4e5f80b', array['Gang cukup lebar, mobil bisa masuk sampai depan kos.', 'Penjaga 24 jam, gerbang digembok jam 23.00 tapi penghuni pegang kunci.', 'Jemuran atap beratap, cucian tetap kering saat hujan.']::text[], array['Listrik token, estimasi kami Rp180.000 kalau pakai AC 8 jam sehari.', 'Cucian dijemur di atap, tangga ke atap agak licin saat hujan.', 'Tidak ada dapur, penghuni biasanya beli makan di warung depan.']::text[], 'Santai, tidak banyak aturan, tapi tidak suka tamu menginap.', array['Tangga darurat digembok saat survei; hanya satu jalan keluar.']::text[]),
  ('7891035d-ae15-4a1c-aab2-057a898d97e9', array['Gang cukup lebar, mobil bisa masuk sampai depan kos.', 'Kunci kamar ganda, pemilik tidak pegang duplikat tanpa izin.', 'Halaman depan ada pohon mangga rindang, sore hari adem.']::text[], array['Kamar mandi luar dipakai bersama 4 kamar.', 'Kamar ukuran 2,5×3 m, lemari built-in tapi tidak ada meja.', 'Pembayaran hanya transfer, tidak terima tunai.']::text[], 'Ramah, tapi tegas soal jam malam dan tamu.', '{}'::text[]),
  ('52bc3502-63a3-4278-a5e2-56292ca314e9', array['Sampah diangkut tiap pagi, tidak ada tumpukan di depan.', 'Air PAM lancar 24 jam, tekanan bagus sampai lantai atas.', 'Water heater gas di semua kamar mandi.']::text[], array['Jam malam 23.00 dan gerbang digembok; telat harus telepon penjaga.', 'Mayoritas penghuni karyawan shift, koridor sepi siang hari.', 'Air kadang keruh setelah hujan deras, pemilik bilang sedang pasang filter.']::text[], 'Profesional, ada resepsionis dan aturan tertulis di lobi.', '{}'::text[]),
