  ('9a5b5c4f-3bd3-4b32-add3-b077fb81cc9e', array['Kamar mandi dikuras setiap hari oleh petugas, tidak ada bau.', 'Air PAM lancar 24 jam, tekanan bagus sampai lantai atas.', 'Water heater gas di semua kamar mandi.']::text[], array['Kontrak minimal 3 bulan, bayar di muka bulan pertama.', 'Mayoritas penghuni karyawan shift, koridor sepi siang hari.', 'Kamar lantai 1 dekat dapur, agak berisik saat jam masak malam.']::text[], 'Pensiunan yang senang mengobrol, hafal nama semua penghuni.', '{}'::text[]),
  ('2aa1a538-5443-4f75-a9d2-b938f30cfbd6', array['Kamar mandi dalam berkeramik penuh, tidak ada nat menghitam.', 'Ventilasi silang di semua kamar, tidak pengap siang hari.', 'Gang cukup lebar, mobil bisa masuk sampai depan kos.']::text[], array['Listrik token, estimasi kami Rp180.000 kalau pakai AC 8 jam sehari.', 'Sinyal Telkomsel lemah di kamar belakang, XL aman.', 'Jam malam 23.00 dan gerbang digembok; telat harus telepon penjaga.']::text[], 'Agak sulit dihubungi siang hari, balas WhatsApp malam.', '{}'::text[]),
  ('ac912cca-5117-4c55-aa2a-c0c1f7c06cd6', array['Sampah diangkut tiap pagi, tidak ada tumpukan di depan.', 'Halaman depan ada pohon mangga rindang, sore hari adem.', 'Air PAM lancar 24 jam, tekanan bagus sampai lantai atas.']::text[], array['Kontrak minimal 3 bulan, bayar di muka bulan pertama.', 'Pembayaran hanya transfer, tidak terima tunai.', 'Tangga curam dan tidak ada lift, bawa barang berat repot.']::text[], 'Sangat rapi, punya buku catatan kerusakan tiap kamar.', '{}'::text[]),
  ('33133cc0-e336-455e-a4df-aadad4bede10', array['Kamar mandi dalam berkeramik penuh, tidak ada nat menghitam.', 'Water heater gas di semua kamar mandi.', 'Pemilik tinggal di lantai 1, balas WhatsApp dalam 10 menit saat kami tes.']::text[], array['Tamu hanya boleh sampai ruang tamu, tidak boleh masuk kamar.', 'Pembayaran hanya transfer, tidak terima tunai.', 'Kamar belakang menghadap tembok, cahaya matahari kurang.']::text[], 'Ramah, tapi tegas soal jam malam dan tamu.', '{}'::text[]),
  ('e57a4c57-5543-41c1-a476-d9f2fcf9fc41', array['Ada dispenser dan galon gratis di tiap lantai.', 'Lampu koridor sensor gerak, terang sampai pagi.', 'Penjaga 24 jam, gerbang digembok jam 23.00 tapi penghuni pegang kunci.']::text[], array['Tamu hanya boleh sampai ruang tamu, tidak boleh masuk kamar.', 'Kontrak minimal 3 bulan, bayar di muka bulan pertama.', 'WiFi bayar sendiri Rp75.000 per bulan ke pemilik.']::text[], 'Dikelola anak pemilik, cepat tanggap soal kerusakan.', '{}'::text[]),
  ('2bf03262-c18a-43d1-ab36-7484938eaaee', array['Penjaga 24 jam, gerbang digembok jam 23.00 tapi penghuni pegang kunci.', 'WiFi kami tes 42 Mbps di kamar paling ujung lantai 2.', 'Listrik token: penghuni isi sendiri, tidak ada tagihan kejutan.']::text[], array['Kamar lantai 1 dekat dapur, agak berisik saat jam masak malam.', 'WiFi bayar sendiri Rp75.000 per bulan ke pemilik.', 'Motor parkir di gang depan, tidak beratap.']::text[], 'Sangat rapi, punya buku catatan kerusakan tiap kamar.', '{}'::text[]);
